def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 4 or (r, c) in seen:
                continue
            seen.add((r, c))
            q = [(r, c)]
            cells = []
            while q:
                x, y = q.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    z = (x + dx, y + dy)
                    if 0 <= z[0] < h and 0 <= z[1] < w and z not in seen and grid[z[0]][z[1]] == color:
                        seen.add(z)
                        q.append(z)
            out.append((color, cells))
    return out

def _shape(cells):
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    return frozenset((r-r0, c-c0) for r, c in cells)

def transform(grid):
    comps = _components(grid)
    # The long L is the directional/color marker.
    marker = None
    for color, cells in comps:
        if len(cells) < 5:
            continue
        rows = {r for r, c in cells}
        cols = {c for r, c in cells}
        for cr in rows:
            for cc in cols:
                if all(r == cr or c == cc for r, c in cells) and (cr, cc) in cells:
